// As cinco fontes testadas para impressao, em base64.
//
// Saíram de dentro do HTML do letreiro no C2. Estavam la porque a pagina era
// uma so; com o topo de bolo sao duas, e 473 KB de base64 duplicados seriam
// 473 KB carregados duas vezes e corrigidos em um lugar so no dia de trocar
// uma fonte.
//
// Arquivo .js e nao .ttf de proposito: as ferramentas de conferencia abrem a
// pagina como file://, e ali o navegador bloqueia fetch mas deixa <script src>
// passar. Foi essa a razao de o nucleo tambem ser .js.
//
// §4 do documento de requisitos: "fontes previamente testadas para impressao
// 3D". Sao estas -- ja passaram pelo letreiro e pela mesa.
(function (root, fabrica) {
  const M = fabrica();
  if (typeof module === 'object' && module.exports) module.exports = M;
  else root.MorumbiFontes = M;
})(typeof window !== 'undefined' ? window : globalThis, function () {
  const luckiest = "";
  const gamer = "";
  const cinema = "";
  const futuro = "";
  const terror = "";

  /** base64 -> ArrayBuffer, do jeito que o opentype espera. */
  function bytes(b64) {
    const bin = typeof atob === 'function' ? atob(b64)
      : Buffer.from(b64, 'base64').toString('binary');
    const buf = new ArrayBuffer(bin.length), u8 = new Uint8Array(buf);
    for (let i = 0; i < bin.length; i++) u8[i] = bin.charCodeAt(i);
    return buf;
  }

  const b64 = { luckiest, gamer, cinema, futuro, terror };

  /** Todas as fontes ja parseadas. Recebe o opentype de quem chamou porque o
   *  parser e do navegador (ou do node), nao deste arquivo. */
  function carregar(opentype) {
    const fora = {};
    for (const nome of Object.keys(b64)) fora[nome] = opentype.parse(bytes(b64[nome]));
    return fora;
  }

  return { b64, bytes, carregar, nomes: Object.keys(b64) };
});
